inputs.manifest:
{
  "schema_version": "1.0.0",
  "id": "krea2/upscale",
  "label": {
    "en": "Upscale",
    "ru": "Апскейл"
  },
  "family": "krea2",
  "family_label": "Krea 2 Turbo",
  "tier": 0,
  "mode": "upscale",
  "order": 43,
  "controls": [
    {
      "param": "prompt",
      "kind": "prompt",
      "superprompt": true
    },
    {
      "param": "scale",
      "kind": "choice",
      "default": 2.0,
      "label": {
        "en": "Enlargement",
        "ru": "Увеличение"
      },
      "options": [
        {
          "value": 1.0,
          "label": "1x",
          "tooltip": {
            "en": "No enlargement - a second pass at the original size.",
            "ru": "Без увеличения — второй проход в исходном размере."
          }
        },
        {
          "value": 2.0,
          "label": "2x",
          "tooltip": {
            "en": "Twice the width and height.",
            "ru": "Вдвое по ширине и высоте."
          }
        },
        {
          "value": 4.0,
          "label": "4x",
          "tooltip": {
            "en": "Four times the width and height - slow, and best with a lower denoise.",
            "ru": "Вчетверо по ширине и высоте — долго, и лучше с меньшим денойзом."
          }
        }
      ]
    },
    {
      "param": "seed",
      "kind": "seed"
    },
    {
      "param": "denoise",
      "kind": "slider",
      "min": 0.05,
      "max": 0.6,
      "step": 0.05,
      "default": 0.35,
      "label": {
        "en": "Detail denoise",
        "ru": "Денойз деталей"
      },
      "tooltip": {
        "en": "How much the pass invents. 0.2-0.3 stays faithful to the source; 0.45 adds noticeable new detail - good at 1x and 2x, heavy-handed when enlarging fourfold.",
        "ru": "Насколько проход домысливает. 0.2–0.3 — верность исходнику; 0.45 заметно добавляет деталей: хорошо для 1x и 2x, многовато при увеличении вчетверо."
      }
    },
    {
      "param": "loras",
      "kind": "loras",
      "max": 8,
      "strength": [
        -2.0,
        2.0
      ]
    },
    {
      "param": "steps",
      "kind": "number",
      "advanced": true,
      "min": 1,
      "max": 30,
      "default": 8,
      "label": {
        "en": "Steps",
        "ru": "Шаги"
      }
    }
  ],
  "refs": {
    "max": 0
  },
  "requires": [
    "source_image"
  ],
  "upscale_params": {
    "image": "source_image"
  },
  "negative_prompt": false,
  "models": [
    {
      "title": "studio:model",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "krea2_turbo_int8_convrot"
    },
    {
      "title": "studio:clip",
      "input": "clip_name",
      "folder": "text_encoders",
      "match": "Qwen3-VL-4B-Instruct-abliterated_int8"
    },
    {
      "title": "studio:vae",
      "input": "vae_name",
      "folder": "vae",
      "match": "qwen_image_vae"
    }
  ]
}
